  <text class="fig-t fig-title" x="197" y="22" text-anchor="middle">break がある</text>
  <text class="fig-t fig-title" x="537" y="22" text-anchor="middle">break を書き忘れた</text>

  <rect class="fig-box-accent" x="44" y="40" width="306" height="44" rx="6"/>
  <text class="fig-t fig-mono fig-small fig-t-accent" x="60" y="56">case 1:</text>
