public class Main {
    // 呼ばれたことが分かるメソッド
    static boolean check(String name, boolean value) {
        System.out.println("  " + name + " を評価した");
        return value;
    }

    public static void main(String[] args) {
        System.out.println("false && ... :");
        boolean a = check("左", false) && check("右", true);
        System.out.println("  結果 " + a);

        System.out.println("false & ... :");
        boolean b = check("左", false) & check("右", true);
        System.out.println("  結果 " + b);

        System.out.println("true || ... :");
        boolean c = check("左", true) || check("右", false);
        System.out.println("  結果 " + c);
    }
}

public class Main {
