import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String raw = sc.next();
        String name = raw.equals("-") ? null : raw;

        System.out.println(n >= 80 ? "A" : n >= 60 ? "B" : "C");
        System.out.println((n == 0 || 100 / n > 5) ? "小さめ" : "大きめ");
        // null の確認を左に置く。右へ置くと name が null のとき length() で落ちる
        System.out.println(name != null && name.length() >= 3 ? "長い名前" : "短いか無し");
    }
}

